  icon?: string;
  image?: string;
  description?: string;
  attributes?: Attribute[];
  createdAt!: string;
  updatedAt!: string;

  // #region 🔖Private State
  private backbone?: Backbone;
  private validationState: ValidationState = { errors: [], warnings: [], infos: [] };
  private isConflicted: boolean = false;
  private strictMode: boolean = false;
  // #endregion 🔖Private State

  constructor(plain: KitPlain, backbone?: Backbone) {
    const p = KitSchema.parse(plain);
    Object.assign(this, p);
    this.types = p.types?.map((t) => new Type(t, this));
    this.designs = p.designs?.map((d) => new Design(d, this));
    this.tags = p.tags?.map((t) => new Tag(t));
    this.concepts = p.concepts?.map((c) => new Concept(c));
    this.ports = p.ports?.map((x) => new Port(x));
    this.qualities = p.qualities?.map((q) => new Quality(q));
    this.files = p.files?.map((f) => new File(f));
    this.folders = p.folders?.map((f) => new Folder(f));
    this.authors = p.authors?.map((a) => new Author(a));
    this.attributes = p.attributes?.map((a) => new Attribute(a));
    this.backbone = backbone;
  }

  /**
   * 🎯Centralized change API. ALL mutations go through this.
   * 1. Validates the diff against current state
   * 2. Blocks on errors
   * 3. Blocks on warnings if strict mode
   * 4. Computes inverse diff from current state
   * 5. Applies diff instantly (mutates in-place)
   * 6. Queues to backbone if present (non-blocking)
   * 7. Clears conflict state on success
   */
  change(diff: KitDiff, meta?: { origin?: string }): KitChange {
    const validation = this.validate(diff);

    if (validation.errors.length > 0) {
      this.isConflicted = true;
      this.validationState = validation;
      throw new Error(`[DEBUG] Validation errors: ${validation.errors.join(", ")}`);
    }

    if (this.strictMode && validation.warnings.length > 0) {
      this.isConflicted = true;
      this.validationState = validation;
      throw new Error(`[DEBUG] Validation warnings in strict mode: ${validation.warnings.join(", ")}`);
    }

    const currentState = this.snapshot();
    const backward = inverseKitDiff(this, diff);

    applyKitDiff(this, diff);

    const change: KitChange = { forward: diff, backward };
    if (this.backbone) {
      this.backbone.changed(change).catch(err => {
        console.error('[DEBUG] Backbone sync error:', err);
      });
    }

    this.isConflicted = false;
    this.validationState = { errors: [], warnings: [], infos: [] };

    return change;
  }

  /**
   * 🔍Validation - check constraints before applying diff.
   */
  private validate(diff: KitDiff): ValidationState {
    const state: ValidationState = { errors: [], warnings: [], infos: [] };
    // Add validation logic here as needed
    return state;
  }

  /**
   * 📸Snapshot - returns immutable view of current state.
   */
  snapshot(): KitPlain {
    return this.toPlain();
  }

  /**
   * Validates and wraps a plain kit object.
   */
  static fromPlain(plain: KitPlain, backbone?: Backbone): Kit {
    return new Kit(plain, backbone);
  }

  /**
   * Applies a kit diff in place (same as `applyKitDiff(this, diff)`).
   */
  applyDiff(diff: KitDiff): void {
    applyKitDiff(this, diff);
  }

  // #region 🔍Finders
  findType(guid: Guid): Type | undefined {
    return this.types?.find(t => t.guid === guid);
  }

  findDesign(guid: Guid): Design | undefined {
    return this.designs?.find(d => d.guid === guid);
  }

  findPiece(designGuid: Guid, pieceGuid: Guid): Piece | undefined {
    const design = this.findDesign(designGuid);
    return design?.pieces?.find(p => p.guid === pieceGuid);
  }

  findConnection(designGuid: Guid, connectionGuid: Guid): Connection | undefined {
    const design = this.findDesign(designGuid);
    return design?.connections?.find(c => c.guid === connectionGuid);
  }
  // #endregion 🔍Finders

  // #region 🔗Getters
  getDiff(other: Kit): KitDiff {
    return getKitDiff(this, other);
  }

  getHash(): string {
    return JSON.stringify(this.toPlain()).split('').reduce((a, b) => {
      a = ((a << 5) - a) + b.charCodeAt(0);
      return a & a;
    }, 0).toString(36);
  }

  isConflict(): boolean {
    return this.isConflicted;
  }

  getValidationState(): ValidationState {
    return { ...this.validationState };
  }

  setStrictMode(strict: boolean): void {
    this.strictMode = strict;
  }
  // #endregion 🔗Getters

  toPlain(): KitPlain {
    return KitSchema.parse(this as unknown as KitPlain);
  }
}

