## Task: Refactor TypeScript Kit API to Object-Oriented Architecture

File: `compose/js/index.ts` (~20K lines)
Ticket: Refactor Kit API To Object-Oriented With Centralized Change Management

### Core Changes

#### 1. Create Kit Class
```typescript
export class Kit {
  private guid: Guid;
  private name: string;
  private version?: string;
  private types: Type[] = [];
  private designs: Design[] = [];
  // ... all other collections
  private backbone?: Backbone;
  private validationState: ValidationState = { errors: [], warnings: [], infos: [] };
  private isConflicted: boolean = false;
  private strictMode: boolean = false;

  constructor(kit: KitData, backbone?: Backbone) {
    // Initialize from data
    this.guid = kit.guid;
    this.name = kit.name;
    // ... etc
  }

  // Main change API - ALL mutations go through this
  change(diff: KitDiff, meta?: { origin?: string }): KitChange {
    // 1. Validate the diff against current state
    const validation = this.validate(diff);

    // 2. Block if errors
    if (validation.errors.length > 0) {
      this.isConflicted = true;
      this.validationState = validation;
      throw new ValidationError(validation.errors);
    }

    // 3. Block if warnings and strict mode
    if (this.strictMode && validation.warnings.length > 0) {
      this.isConflicted = true;
      this.validationState = validation;
      throw new ValidationError(validation.warnings);
    }

    // 4. Compute inverse diff from current state
    const currentState = this.snapshot();
    const backward = inverseKitDiff(currentState, diff);

    // 5. Apply diff instantly (mutates in-place)
    applyKitDiff(this, diff);

    // 6. Queue to backbone if present (non-blocking)
    const change: KitChange = { forward: diff, backward };
    if (this.backbone) {
      this.backbone.changed(change).catch(err => {
        // Log backbone error but keep kit in sync
        console.error('[DEBUG] Backbone sync error:', err);
      });
    }

    // 7. Clear conflict state on success
    this.isConflicted = false;
    this.validationState = { errors: [], warnings: [], infos: [] };

    return change;
  }

  // Read-only snapshots
  snapshot(): KitData { /* return immutable view */ }

  // Validation
  private validate(diff: KitDiff): ValidationState { /* check constraints */ }

  // Properties (read-only)
  get Types(): readonly Type[] { return this.types; }
  get Designs(): readonly Design[] { return this.designs; }
  // ... etc

  // Finders (replace find* functions)
  findType(guid: Guid): Type | undefined { return this.types.find(t => t.guid === guid); }
  findDesign(guid: Guid): Design | undefined { return this.designs.find(d => d.guid === guid); }
  findPiece(designGuid: Guid, pieceGuid: Guid): Piece | undefined { 
    const design = this.findDesign(designGuid);
    return design?.Pieces.find(p => p.guid === pieceGuid);
  }
  // ... all find* functions

  // Getters (replace get* functions)
  getDiff(other: Kit): KitDiff { return getKitDiff(this.snapshot(), other.snapshot()); }
  getHash(): string { return hashKit(this.snapshot()); }

  // Import/Export (replace functions)
  static async fromTransport(transport: TransportKit): Promise<Kit> {
    const kit = transport.toKit();
    return new Kit(kit);
  }

  async toTransport(): Promise<TransportKit> {
    return TransportKit.fromKit(this.snapshot());
  }
}
